class CarDetailScreen extends StatefulWidget{final Car? car; const CarDetailScreen({super.key,this.car}); @override State<CarDetailScreen> createState()=>_CarDetailScreenState();}
class _CarDetailScreenState extends State<CarDetailScreen>{final repo=CarRepository(); final picker=ImagePicker(); final make=TextEditingController(),model=TextEditingController(),year=TextEditingController(),vin=TextEditingController(),plate=TextEditingController(),mileage=TextEditingController(),purchase=TextEditingController(),seller=TextEditingController(),notes=TextEditingController(),sale=TextEditingController(); String status='Куплен'; DateTime purchaseDate=DateTime.now(); int? id; double expensesTotal=0; List<Map<String,Object?>> expenses=[]; List<Attachment> attachments=[]; List<Map<String,Object?>> cats=[]; bool saved=false;
 double money(String s)=>double.tryParse(s.replaceAll(' ','').replaceAll(',','.'))??0;
 @override void initState(){super.initState(); final c=widget.car; if(c!=null){id=c.id;make.text=c.make;model.text=c.model;year.text='${c.year??''}';vin.text=c.vin;plate.text=c.plate;mileage.text='${c.mileage??''}';purchase.text=c.purchasePrice.toStringAsFixed(0);seller.text=c.seller;notes.text=c.notes;sale.text=c.salePrice?.toStringAsFixed(0)??'';status=c.status;purchaseDate=c.purchaseDate; loadExtra();} else {purchase.text='0';} catsLoad();}
 Future<void> catsLoad()async{cats=await repo.categories();setState((){});} Future<void> loadExtra()async{if(id==null)return;expenses=await repo.expenses(id!);expensesTotal=await repo.totalExpenses(id!);attachments=await repo.attachments(id!);setState((){});}
 Future<void> save()async{if(make.text.trim().isEmpty||model.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Укажите марку и модель')));return;} id=await repo.saveCar(Car(id:id,make:make.text.trim(),model:model.text.trim(),year:int.tryParse(year.text),vin:vin.text.trim(),plate:plate.text.trim(),mileage:int.tryParse(mileage.text),purchaseDate:purchaseDate,purchasePrice:money(purchase.text),seller:seller.text.trim(),notes:notes.text.trim(),status:status,salePrice:sale.text.trim().isEmpty?null:money(sale.text))); saved=true; await loadExtra();}
 Future<void> addPhoto(ImageSource source)async{if(id==null)await save();if(id==null)return;final x=await picker.pickImage(source:source,imageQuality:90);if(x==null)return;final path=await FileService.copyIntoApp(x.path,x.name);await repo.addAttachment(Attachment(carId:id!,path:path,name:x.name,type:'image'));await loadExtra();}
 Future<void> addFile()async{if(id==null)await save();if(id==null)return;final r=await FilePicker.platform.pickFiles();if(r==null||r.files.single.path==null)return;final f=r.files.single;final path=await FileService.copyIntoApp(f.path!,f.name);await repo.addAttachment(Attachment(carId:id!,path:path,name:f.name,type:'file'));await loadExtra();}
 Future<void> addExpense()async{if(id==null)await save();if(id==null)return; if(cats.isEmpty)return; int catId=cats.first['id'] as int; final amount=TextEditingController();final note=TextEditingController(); final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Новый расход'),content:StatefulBuilder(builder:(c,set)=>Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(initialValue:catId,items:cats.map((x)=>DropdownMenuItem(value:x['id'] as int,child:Text(x['name'] as String))).toList(),onChanged:(v)=>set(()=>catId=v!),decoration:const InputDecoration(labelText:'Категория')),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Сумма')),TextField(controller:note,decoration:const InputDecoration(labelText:'Комментарий'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Отмена')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Добавить'))])); if(ok==true&&money(amount.text)>0){await repo.addExpense(Expense(carId:id!,categoryId:catId,amount:money(amount.text),date:DateTime.now(),note:note.text));await loadExtra();}}
 Future<void> newCategory()async{final t=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Новая категория'),content:TextField(controller:t,autofocus:true,decoration:const InputDecoration(hintText:'Например: Страховка')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Отмена')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Создать'))]));if(ok==true&&t.text.trim().isNotEmpty){await repo.addCategory(t.text);await catsLoad();}}
 @override Widget build(BuildContext c){final invested=money(purchase.text)+expensesTotal;final profit=(sale.text.trim().isEmpty?0:money(sale.text))-invested;return Scaffold(appBar:AppBar(title:Text(widget.car==null?'Новый автомобиль':'${make.text} ${model.text}'),actions:[IconButton(onPressed:save,icon:const Icon(Icons.save))]),body:ListView(padding:const EdgeInsets.all(12),children:[_section('Автомобиль',[Row(children:[Expanded(child:_f(make,'Марка')),Expanded(child:_f(model,'Модель'))]),Row(children:[Expanded(child:_f(year,'Год',keyboard:TextInputType.number)),Expanded(child:_f(mileage,'Пробег',keyboard:TextInputType.number))]),_f(vin,'VIN'),_f(plate,'Госномер'),_f(seller,'Продавец'),DropdownButtonFormField<String>(initialValue:status,items:['Куплен','В ремонте','Готов к продаже','На продаже','Продан'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>status=v!),decoration:const InputDecoration(labelText:'Статус')),ListTile(contentPadding:EdgeInsets.zero,title:const Text('Дата покупки'),subtitle:Text(DateFormat('dd.MM.yyyy').format(purchaseDate)),trailing:const Icon(Icons.calendar_month),onTap:()async{final d=await showDatePicker(context:c,firstDate:DateTime(2000),lastDate:DateTime(2100),initialDate:purchaseDate);if(d!=null)setState(()=>purchaseDate=d);})]),_section('Деньги',[Row(children:[Expanded(child:_f(purchase,'Цена покупки',keyboard:TextInputType.number)),const SizedBox(width:8),Expanded(child:_f(sale,'Цена продажи',keyboard:TextInputType.number))]),Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Вложено: ${invested.toStringAsFixed(0)} ₽',style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)),Text('Расходы: ${expensesTotal.toStringAsFixed(0)} ₽'),Text('Прибыль: ${profit.toStringAsFixed(0)} ₽',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold,color:profit>=0?Colors.green:Colors.red))])))]),_section('Расходы',[Row(children:[FilledButton.icon(onPressed:addExpense,icon:const Icon(Icons.add),label:const Text('Расход')),const SizedBox(width:8),OutlinedButton.icon(onPressed:newCategory,icon:const Icon(Icons.category),label:const Text('Категория'))]),...expenses.map((e)=>ListTile(contentPadding:EdgeInsets.zero,title:Text('${e['category_name']} — ${(e['amount'] as num).toStringAsFixed(0)} ₽'),subtitle:Text(e['note'] as String? ?? ''),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{await repo.deleteExpense(e['id'] as int);await loadExtra();}))]),_section('Фото и документы',[Wrap(spacing:8,runSpacing:8,children:[OutlinedButton.icon(onPressed:()=>addPhoto(ImageSource.camera),icon:const Icon(Icons.camera_alt),label:const Text('Камера')),OutlinedButton.icon(onPressed:()=>addPhoto(ImageSource.gallery),icon:const Icon(Icons.photo_library),label:const Text('Фото')),OutlinedButton.icon(onPressed:addFile,icon:const Icon(Icons.attach_file),label:const Text('Документ'))]),...attachments.map((a)=>ListTile(contentPadding:EdgeInsets.zero,leading:Icon(a.type=='image'?Icons.image:Icons.picture_as_pdf),title:Text(a.name,maxLines:1,overflow:TextOverflow.ellipsis),onTap:()=>OpenFilex.open(a.path),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{await repo.deleteAttachment(a.id!);try{await File(a.path).delete();}catch(_){}await loadExtra();}))]),_section('Заметки',[_f(notes,'Комментарий',maxLines:4)]),const SizedBox(height:100)]));}
 Widget _section(String title,List<Widget> children)=>Padding(padding:const EdgeInsets.only(bottom:18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.only(bottom:8),child:Text(title,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold))),...children]));
 Widget _f(TextEditingController c,String label,{TextInputType? keyboard,int maxLines=1})=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:c,onChanged:(_)=>setState((){}),keyboardType:keyboard,maxLines:maxLines,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
}
